    {
      "step": 1,
      "title": "Check basic connection state",
      "instructions": [
        "Run check_network_status on your phone.",
        "Please share back the results for: Airplane Mode, Signal Strength, Network Type (e.g., 5G/4G/3G/2G), Mobile Data (ON/OFF), and Data Roaming (ON/OFF)."
      ]
    },
    {
      "step": 2,
