        "If check_network_status shows Mobile Data is OFF, turn it ON using toggle_data.",
        "If Data Roaming is OFF, turn it ON using toggle_roaming."
      ],
      "after_action": "Run run_speed_test and tell me the result label (unknown/very poor/poor/fair/good/excellent)."
    },
    {
      "step": 3,
      "title": "Use the fastest network modes",
      "instructions": [
        "Run check_network_mode_preference.",
        "If it is set to 2G or 3G, switch to set_network_mode_preference with mode \"4g_5g_preferred\".",
        "If you see unstable 5G, you can also try \"4g_only\" for consistency; let me know which you choose."
      ],
      "after_action": "Run run_speed_test again and share the result."
    },
    {
      "step": 4,
      "title": "Disable features that can slow data",
      "instructions": [
        "Run check_data_restriction_status. If Data Saver mode is ON, turn it OFF using toggle_data_saver_mode.",
        "Run check_vpn_status. If a VPN is connected, use disconnect_vpn."
      ],
      "after_action": "Run run_speed_test again and share the result."
    },
    {
      "step": 5,
      "title": "Refresh the cellular data session",
      "instructions": [
        "Use toggle_data to turn Mobile Data OFF, wait 10 seconds, then turn it ON.",
        "If data is still not excellent, use toggle_airplane_mode to turn Airplane Mode ON for 15 seconds, then OFF."
      ],
      "after_action": "Run run_speed_test again and share the result."
    },
    {
      "step": 6,
      "title": "Verify APN settings (fixes roaming data issues)",
      "instructions": [
        "Run check_apn_settings and tell me what it reports, especially the APN name and whether MMSC is set.",
        "If it indicates incorrect/missing settings, run reset_apn_settings.",
        "After resetting APN, run reboot_device to restart your phone."
      ],
      "after_action": "Once back up, run run_speed_test and share the result."
    },
    {
      "step": 7,
      "title": "SIM refresh (only if no signal or persistent failure)",
      "instructions": [
        "If earlier steps show SIM issues or you still have no data with signal present, run reseat_sim_card, then run reboot_device."
      ],
      "after_action": "Run run_speed_test and share the result."
    }
  ],
  "about_refueling": {
    "can_refuel_now": true,
    "max_refuel_gb": 2,
    "price_total_for_2gb_usd": 4.0,
    "important_note": "Refueling adds data capacity when you hit your plan limit; it does not increase speed. You still have 6.3 GB left this cycle, so refueling won’t improve speed right now. If you still want to add 2.0 GB for peace of mind, say: \"Refuel 2.0 GB now.\""
  },
  "next_steps_for_you": [
    "Please perform Step 1 and Step 2 and paste the outputs (especially the run_speed_test label).",
    "If speed is not excellent, continue through Steps 3–6 and share each run_speed_test result so I can adjust the next actions."
  ],
  "notes": "Roaming speeds depend on local partner networks. We’ve enabled roaming on your line already; optimizing your device settings typically yields the best available performance while abroad.",
  "confirmation_requests": [
    "Do you want me to proceed with a 2.0 GB refuel for $4 now, or hold off?",
    "After Step 2, what are the exact results for check_network_status and run_speed_test?"
  ]
}

