      "step": "5",
      "action": "Test MMS capability.",
      "how": "Run can_send_mms, or try sending yourself a photo MMS.",
      "reason": "Verifies whether MMS can send after the above changes."
    },
    {
      "step": "6",
      "action": "If MMS still fails, check APN/MMSC.",
      "how": "Run check_apn_settings. If MMSC URL is missing/incorrect, use reset_apn_settings, then use reboot_device.",
      "reason": "Incorrect MMSC is a very common cause of MMS failure, especially when roaming."
    },
    {
      "step": "7",
      "action": "If still not working, check the messaging app permissions.",
      "how": "Run check_app_permissions with app_name=\"messaging\". If storage or sms are missing, use grant_app_permission for \"storage\" and \"sms\".",
      "reason": "The app must access media and SMS/MMS functions."
    },
    {
      "step": "8",
      "action": "If you’re using a VPN, disconnect it.",
      "how": "Run check_vpn_status. If connected and speeds are poor, use disconnect_vpn.",
      "reason": "VPNs can block or slow MMS/data while roaming."
    }
  ],
  "about_refueling": {
    "need": "Not needed right now based on your current usage.",
    "pricing": "If you still want it later, your plan’s data refuel price is $2.00 per GB. A 2.0 GB refill would cost $4.00 (max refuel per request is 2 GB).",
    "note": "We can add it anytime upon your confirmation."
