  "quick_questions": [
    "Are you in your usual location or somewhere new (e.g., basement, elevator, rural area)?",
    "Do you have another line/device nearby (e.g., 555-123-2001 on your account)? If yes, does it have signal in the same spot?"
  ],
  "steps": [
    {
      "step": 1,
      "title": "Check SIM status",
      "tool": "check_sim_status",
      "instructions": [
        "On iPhone: Settings > Cellular > SIM Status (or Settings > General > About > scroll to network/SIM info).",
        "On Android: Settings > About phone > SIM status (or Settings > Connections > SIM manager)."
      ],
      "what_to_share": "Tell me if it shows Active, Missing, or Locked (PIN/PUK).",
      "next_actions_based_on_result": {
        "Active": "Proceed to Step 2.",
        "Missing": "We’ll reseat the SIM next (power off, remove and reinsert SIM, then power on).",
        "Locked": "Do not guess the PIN/PUK. I will transfer you to a specialist for SIM security."
      }
    },
    {
      "step": 2,
      "title": "Check overall network status",
      "tool": "check_network_status",
      "instructions": [
        "Look for: signal strength (none/poor/fair/good/excellent), network type (5G/4G/3G), Mobile Data (enabled/disabled), and Data Roaming (on/off)."
      ],
      "what_to_share": "Report exactly what it shows for signal strength, network type, Mobile Data, and Roaming."
    },
    {
      "step": 3,
      "title": "Verify preferred network mode",
      "tool": "check_network_mode_preference",
      "instructions": [
