messages.content:
{
  "message": "I can help. Because MMS depends on both your account (roaming, data) and your phone’s settings, I’ll first verify your line and then walk you through a few quick checks. Here’s the plan and why: we’ll (1) confirm your account/line and roaming status (so MMS can work abroad), (2) confirm your phone has mobile data and roaming enabled, and (3) confirm the MMS server (MMSC) and a couple of settings that frequently block MMS while overseas.",
  "what_i_need_from_you_to_identify_your_account": {
    "provide_one_of": [
      "The phone number of the affected line",
      "OR your full name + date of birth (YYYY-MM-DD). You already gave your name; DOB helps me look up the correct account."
    ],
    "note": "If roaming is disabled on your line, I can enable it at no cost once I locate your account. Please confirm that’s OK."
  },
  "quick_questions_to_narrow_it_down": [
    "Can you place/receive regular calls and send/receive plain SMS texts right now?",
    "When you turn OFF Wi‑Fi, can you browse the web using mobile data?"
  ],
  "on_device_checks_to_run_and_share_results": [
    {
      "action": "check_network_status",
      "what_to_share": "Airplane mode status, signal strength, network type (e.g., 4G/5G/3G/2G), Mobile Data = ON/OFF, and Data Roaming = ON/OFF.",
      "why": "MMS needs cellular service, mobile data ON, and (while abroad) data roaming ON."
    },
    {
      "action": "check_status_bar",
      "what_to_share": "Any icons shown for Airplane Mode, signal bars, ‘5G/4G/3G/2G’, ‘Data Enabled/Disabled’, ‘Data Saver’, Wi‑Fi (and SSID), VPN.",
      "why": "Confirms at a glance whether anything obvious is blocking data/MMS."
    },
    {
      "action": "check_apn_settings",
      "what_to_share": "Current APN name and the MMSC URL value.",
      "why": "An incorrect or missing MMSC URL will prevent MMS from sending."
    },
    {
      "action": "check_wifi_calling_status",
      "what_to_share": "Whether Wi‑Fi Calling is ON or OFF.",
      "why": "Some configurations can interfere with MMS while abroad."
    },
    {
      "action": "check_vpn_status",
      "what_to_share": "Whether a VPN is connected.",
      "why": "A VPN can sometimes block or slow MMS traffic."
    }
  ],
  "next_steps_after_you_reply": "Once I have your phone number (or name + DOB) and the outputs above, I’ll: (1) check your line’s roaming setting and enable it if needed (with your OK), and (2) guide you through any fixes such as turning on mobile data/roaming, switching network mode off 2G, resetting APN/MMSC and rebooting, temporarily disabling Wi‑Fi Calling or VPN, and then we’ll test sending an MMS again."
}

