messages.content:
{
  "empathy": "I’m sorry this is happening. We’ll keep things simple and safe. I’ll guide you step by step.",
  "reassurance_about_photos": "Restarting (rebooting) your phone does NOT delete your photos. A restart just turns the phone off and on again. Your pictures stay on the phone. If you were taking a photo right now, just make sure it’s saved in your Photos/Gallery first.",
  "what_i_need_from_you_to_get_started": [
    "Your phone number on the account (best option), OR your full name and date of birth (YYYY-MM-DD) for verification.",
    "What kind of phone you have: iPhone or Android.",
    "Are you traveling outside your usual area right now (out of town or abroad)?"
  ],
  "what_we_will_try_first_and_why": "MMS (picture messages) needs regular cell service and mobile data. First we’ll make sure those are on and working. These checks are safe and quick.",
  "simple_steps": [
    {
      "step": "1) Make sure Airplane Mode is OFF",
      "why": "Airplane Mode blocks calls, texts, and data.",
      "how_iphone": "Open Control Center (swipe down from top-right on newer iPhones, or up from bottom on older). If the airplane icon is orange, tap it to turn it gray (OFF).",
      "how_android": "Swipe down from the top to open Quick Settings. If you see an airplane icon highlighted, tap it to turn it OFF."
    },
    {
      "step": "2) Turn Mobile/Cellular Data ON",
      "why": "Picture messages need mobile data (even if Wi‑Fi is on).",
      "how_iphone": "Settings > Cellular (or Mobile Data) > turn Cellular Data ON.",
      "how_android": "Swipe down for Quick Settings > make sure Mobile Data is ON. Or Settings > Network & Internet > SIMs (or Mobile network) > turn Mobile data ON."
    },
    {
      "step": "3) Check your signal",
      "what_to_look_for": "At the top of the screen, you should see signal bars and a label like 4G/LTE/5G. Tell me what you see (for example: 3 bars and LTE)."
    },
    {
      "step": "4) Quick data test",
      "how": "Turn Wi‑Fi OFF for a moment, then open a website (like example.com) in your browser.",
      "what_to_report": "Tell me if the page loads or not."
    },
    {
      "step": "5) Try one small test photo",
      "how": "Open your messaging app and send a small photo to your own number.",
      "what_to_report": "Tell me if it sends, gets stuck, or shows an error."
    }
  ],
  "important_note": "Please keep Mobile/Cellular Data ON while trying to send the picture. MMS won’t work if mobile data is OFF.",
  "please_reply_with": [
    "The phone number on your account (or your full name + DOB for verification).",
    "iPhone or Android.",
    "Whether you’re traveling outside your usual area.",
    "Results of steps 1–5: airplane mode status, if mobile data is ON, what the signal and network label show, whether a webpage loaded with Wi‑Fi off, and what happened when sending a test photo."
  ],
  "next_steps_after_your_reply": "Once I identify your account and see your answers, I’ll guide you through the next simplest fix (only if needed), like a safe settings reset for picture messaging. We’ll go one small step at a time."
}

