    "proposal": "Add 2.0 GB of data now (you said you’re willing to refuel).",
    "price_per_gb": 2.0,
    "total": 4.0,
    "billing": "The charge will be added to your bill.",
    "next_step": "Reply with: Yes, refuel 2 GB — and I’ll add it immediately."
  },
  "steps_for_your_phone": [
    {
      "step": "1) Core connectivity check",
      "what_to_do": [
        "Run check_network_status and tell me what it shows for: Airplane Mode, Signal, Network Type (e.g., 4G/5G), Mobile Data, and Data Roaming.",
        "If Airplane Mode is ON, use toggle_airplane_mode to turn it OFF.",
        "If Mobile Data is OFF, use toggle_data to turn it ON.",
        "If Data Roaming is OFF, use toggle_roaming to turn it ON."
      ],
      "why": "MMS requires mobile data and, when abroad, roaming must be enabled on the device too."
    },
    {
      "step": "2) Preferred network mode",
      "what_to_do": [
        "Run check_network_mode_preference.",
        "If it shows 2G or 3G, use set_network_mode_preference to set \"4g_5g_preferred\"."
      ],
      "why": "2G/3G can break MMS; 4G/5G preferred is required for reliable MMS data."
    },
    {
      "step": "3) Wi‑Fi Calling",
      "what_to_do": [
        "Run check_wifi_calling_status.",
        "If Wi‑Fi Calling is ON, use toggle_wifi_calling to turn it OFF temporarily."
      ],
      "why": "Some configurations interfere with MMS while roaming."
    },
    {
      "step": "4) Data Saver and VPN",
      "what_to_do": [
        "Run check_data_restriction_status; if Data Saver is ON, use toggle_data_saver_mode to turn it OFF.",
        "Run check_vpn_status; if a VPN is connected, use disconnect_vpn."
      ],
      "why": "Data Saver and VPNs can block/slow MMS data, especially abroad."
    },
    {
      "step": "5) APN/MMSC settings",
      "what_to_do": [
        "Run check_apn_settings and tell me the APN name and whether an MMSC URL is present.",
        "If MMSC is missing/incorrect, use reset_apn_settings, then use reboot_device to restart the phone."
      ],
      "why": "A correct MMSC in APN settings is required to send/receive MMS."
    },
    {
      "step": "6) Messaging app permissions",
      "what_to_do": [
        "Run check_app_permissions with app_name=\"messaging\".",
        "If storage or sms permissions are missing, grant them with grant_app_permission for \"storage\" and \"sms\"."
      ],
      "why": "The app needs access to media and SMS to send MMS."
    },
    {
      "step": "7) Test",
      "what_to_do": [
        "After refuel completes and the above checks are good, run can_send_mms.",
        "Then try sending a small picture to your own number as a test."
      ],
      "why": "Confirms MMS is restored."
    }
  ],
  "what_i_need_from_you": [
    "Please confirm: “Yes, refuel 2 GB” so I can add the data immediately.",
    "Share the readout from check_network_status (Airplane Mode, Signal, Network Type, Mobile Data, Data Roaming).",
    "Let me know the result of check_apn_settings (APN name and whether MMSC is set)."
  ],
  "notes": "Once I refuel 2 GB and your device has Mobile Data + Data Roaming ON with correct APN/MMSC, MMS should work. If we reset APN, a reboot is necessary. I’ll stay with you step‑by‑step until it’s sending."
