messages.content:
{
  "acknowledgement": "Great work so far—APN/MMSC now looks correct. Let’s clear the remaining app/device factors that can block MMS.",
  "plan_and_reasoning": "We’ll start with app permissions (a common hard block), then rule out Wi‑Fi Calling conflicts, Data Saver restrictions, and VPN interference. After each fix, we’ll test MMS.",
  "steps_for_your_device": [
    {
      "step": "1) Messaging app permissions",
      "actions": [
        "Run check_app_permissions with app_name=\"messaging\".",
        "If either \"storage\" or \"sms\" is NOT granted, grant both:",
        "• grant_app_permission(app_name=\"messaging\", permission=\"storage\")",
        "• grant_app_permission(app_name=\"messaging\", permission=\"sms\")"
      ],
      "then_test": "Run can_send_mms. If it still cannot send, continue to Step 2."
    },
    {
      "step": "2) Wi‑Fi Calling",
      "actions": [
        "Run check_wifi_calling_status.",
        "If Wi‑Fi Calling is ON, use toggle_wifi_calling to turn it OFF."
      ],
      "then_test": "Run can_send_mms. If still not sending, proceed."
    },
    {
      "step": "3) Data Saver",
      "actions": [
        "Run check_data_restriction_status.",
        "If Data Saver is ON, use toggle_data_saver_mode to turn it OFF."
      ],
      "then_test": "Run can_send_mms. If still not sending, proceed."
    },
    {
      "step": "4) VPN",
      "actions": [
        "Run check_vpn_status.",
        "If a VPN is connected, use disconnect_vpn."
      ],
      "then_test": "Run can_send_mms."
    }
  ],
  "final_check": [
    "After completing the above, try sending a small photo to your own number.",
    "If it fails, please share: ",
    "- Results from check_app_permissions (which permissions were granted)",
    "- Wi‑Fi Calling status, Data Saver status, VPN status",
    "- The latest can_send_mms result"
  ],
  "next_steps_if_still_failing": "If MMS still won’t send after all the above and with MMSC set, I’ll review your outputs. If the issue appears to be app-specific beyond our tooling (e.g., per‑app background data restrictions we can only read), I’ll escalate you to a specialist."
}

